// openings/book.ts
var BOOK = openings_default;
var epdOf = (fen) => fen.split(" ").slice(0, 4).join(" ");
var families = () => BOOK.families;
function isBookPosition(fen) {
  return BOOK.positions[epdOf(fen)] !== void 0;
}
